  }

  /* --- hud clock --- */
  const secs = Math.floor(t);
  if (secs !== lastHud){
    lastHud = secs;
    const mm = String(Math.floor(secs/60)).padStart(2,'0');
    const ss = String(secs%60).padStart(2,'0');
    hudTime.textContent = mm + ':' + ss;
  }

  /* --- TEMP DEBUG report --- */
  if ((dbgFrame += 1) % 12 === 0){
    dbgRay.setFromCamera(new THREE.Vector2(0,0), camera);
    const hits = dbgRay.intersectObjects(scene.children, true);
    let desc = 'MISS';
    if (hits.length){
      const h = hits[0], m = h.object.material;
      desc = `${h.object.name||h.object.geometry.type} @(${h.object.position.x.toFixed(1)},${h.object.position.y.toFixed(1)},${h.object.position.z.toFixed(1)}) col=0x${m.color.getHexString()} emi=${m.emissive?'0x'+m.emissive.getHexString():'-'} op=${m.opacity} map=${!!m.map} d=${h.distance.toFixed(1)}`;
    }
    dbgEl.textContent = 'cam=(' + camera.position.x.toFixed(1) + ',' + camera.position.y.toFixed(1) + ',' + camera.position.z.toFixed(1) + ') tgt=(' + controls.target.x.toFixed(1) + ',' + controls.target.y.toFixed(1) + ',' + controls.target.z.toFixed(1) + ') bg=0x' + scene.background.getHexString() + ' | center: ' + desc;
  }
  renderer.render(scene, camera);
}

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
