  renderer.setSize(window.innerWidth, window.innerHeight);
});

renderer.setAnimationLoop(animate);
reportError(null); // clear any earlier message: scene is live
errEl.style.display = 'none';

}catch(err){
  reportError(err && err.stack ? err.stack : String(err));
}

